import{_ as l,a0 as t,w as o,s as h,ao as d,I as p,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"精通 Linux 上的文件搜索 | LCTT x X-CMD","titleTemplate":false,"description":"精通 Linux 上的文件搜索 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通 Linux 上的文件搜索 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通 Linux 上的文件搜索 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170921 Mastering file searches on Linux","title":"精通 Linux 上的文件搜索","tag":"201801","desc":""},"relativePath":"201801/20170921 Mastering file searches on Linux.md","filePath":"[post].md"}'),r={name:"201801/20170921 Mastering file searches on Linux.md"};function c(g,s,k,u,b,m){const e=t("Link");return o(),h("div",null,[s[13]||(s[13]=d(`<h1 id="精通-linux-上的文件搜索" tabindex="-1">精通 Linux 上的文件搜索 <a class="header-anchor" href="#精通-linux-上的文件搜索" aria-label="Permalink to “精通 Linux 上的文件搜索”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2017/09/telescope-100736548-large.jpg" alt=""></p><p>在 Linux 系统上搜索文件的方法有很多，有的命令很简单，有的很详细。我们的目标是：缩小搜索范围，找到您正在寻找的文件，又不受其他文件的干扰。在今天的文章中，我们将研究一些对文件搜索最有用的命令和选项。我们将涉及：</p><ul><li>快速搜索</li><li>更复杂的搜索条件</li><li>组合条件</li><li>反转条件</li><li>简单和详细的回应</li><li>寻找重复的文件</li></ul><p>有很多有用的命令可以搜索文件，<code>find</code> 命令可能是其中最有名的，但它不是唯一的命令，也不一定总是找到目标文件的最快方法。</p><h3 id="快速搜索命令-which-和-locate" tabindex="-1">快速搜索命令：which 和 locate <a class="header-anchor" href="#快速搜索命令-which-和-locate" aria-label="Permalink to “快速搜索命令：which 和 locate”">​</a></h3><p>搜索文件的最简单的命令可能就是 <code>which</code> 和 <code>locate</code> 了，但二者都有一些局限性。<code>which</code> 命令只会在系统定义的搜索路径中，查找可执行的文件，通常用于识别命令。如果您对输入 <code>which</code> 时会运行哪个命令感到好奇，您可以使用命令 <code>which which</code>，它会指出对应的可执行文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which which</span></span>
<span class="line"><span>/usr/bin/which</span></span></code></pre></div><p><code>which</code> 命令会显示它找到的第一个以相应名称命名的可执行文件（也就是使用该命令时将运行的那个文件），然后停止。</p><p><code>locate</code> 命令更大方一点，它可以查找任意数量的文件，但它也有一个限制：仅当文件名被包含在由 <code>updatedb</code> 命令构建的数据库时才有效。该文件可能会存储在某个位置，如 <code>/var/lib/mlocate/mlocate.db</code>，但不能用 <code>locate</code> 以外的任何命令读取。这个文件的更新通常是通过每天通过 cron 运行的 <code>updatedb</code> 进行的。</p><p>简单的 <code>find</code> 命令没有太多限制，不过它需要指定搜索的起点和搜索条件。最简单的 <code>find</code> 命令：按文件名搜索文件。如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme</span></span>
<span class="line"><span>./bin/runme</span></span></code></pre></div><p>如上所示，通过文件名搜索文件系统的当前位置将会搜索所有子目录，除非您指定了搜索深度。</p><h3 id="不仅仅是文件名" tabindex="-1">不仅仅是文件名 <a class="header-anchor" href="#不仅仅是文件名" aria-label="Permalink to “不仅仅是文件名”">​</a></h3><p><code>find</code> 命令允许您搜索除文件名以外的多种条件，包括文件所有者、组、权限、大小、修改时间、缺少所有者或组，和文件类型等。除了查找文件外，您还可以删除文件、对其进行重命名、更改所有者、更改权限和对找到的文件运行几乎任何命令。</p><p>下面两条命令会查找：在当前目录中 root 用户拥有的文件，以及不被指定用户（在本例中为 shs）所拥有的文件。在这个例子中，两个输出是一样的，但并不总是如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -user root -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./xyz -&gt; /home/peanut/xyz</span></span>
<span class="line"><span>$ find . ! -user shs -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./xyz -&gt; /home/peanut/xyz</span></span></code></pre></div><p>感叹号 <code>!</code> 字符代表“非”：反转跟随其后的条件。</p><p>下面的命令将查找具有特定权限的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -perm 750 -ls</span></span>
<span class="line"><span> 397176 4 -rwxr-x--- 1 shs shs 115 Sep 14 13:52 ./ll</span></span>
<span class="line"><span> 398209 4 -rwxr-x--- 1 shs shs 117 Sep 21 08:55 ./get-updates</span></span>
<span class="line"><span> 397145 4 drwxr-x--- 2 shs shs 4096 Sep 14 15:42 ./newdir</span></span></code></pre></div><p>接下来的命令显示具有 777 权限的非符号链接文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -perm 777 ! -type l -ls</span></span>
<span class="line"><span> 397132 4 -rwxrwxrwx 1 shs shs 18 Sep 15 16:06 /home/shs/bin/runme</span></span>
<span class="line"><span> 396949 4 -rwxrwxrwx 1 root root 558 Sep 21 11:21 /home/oops</span></span></code></pre></div><p>以下命令将查找大小超过千兆字节的文件。请注意，我们找到了一个非常有趣的文件。它以 ELF core 文件格式表示了该系统的物理内存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find / -size +1G -ls</span></span>
<span class="line"><span> 4026531994 0 -r-------- 1 root root 140737477881856 Sep 21 11:23 /proc/kcore</span></span>
<span class="line"><span> 1444722 15332 -rw-rw-r-- 1 shs shs 1609039872 Sep 13 15:55 /home/shs/Downloads/ubuntu-17.04-desktop-amd64.iso</span></span></code></pre></div><p>只要您知道 <code>find</code> 命令是如何描述文件类型的，就可以通过文件类型来查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b = 块设备文件</span></span>
<span class="line"><span>c = 字符设备文件</span></span>
<span class="line"><span>d = 目录</span></span>
<span class="line"><span>p = 命名管道</span></span>
<span class="line"><span>f = 常规文件</span></span>
<span class="line"><span>l = 符号链接</span></span>
<span class="line"><span>s = 套接字</span></span>
<span class="line"><span>D = 门（仅限 Solaris）</span></span></code></pre></div><p>在下面的命令中，我们要寻找符号链接和套接字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./whatever -&gt; /home/peanut/whatever</span></span>
<span class="line"><span>$ find . -type s -ls</span></span>
<span class="line"><span> 395256 0 srwxrwxr-x 1 shs shs 0 Sep 21 08:50 ./.gnupg/S.gpg-agent</span></span></code></pre></div><p>您还可以根据 inode 号来搜索文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -inum 397132 -ls</span></span>
<span class="line"><span> 397132 4 -rwx------ 1 shs shs 18 Sep 15 16:06 ./bin/runme</span></span></code></pre></div><p>另一种通过 inode 搜索文件的方法是使用 <code>debugfs</code> 命令。在大的文件系统上，这个命令可能比 <code>find</code> 快得多，您可能需要安装 icheck。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo debugfs -R &#39;ncheck 397132&#39; /dev/sda1</span></span>
<span class="line"><span>debugfs 1.42.13 (17-May-2015)</span></span>
<span class="line"><span>Inode Pathname</span></span>
<span class="line"><span>397132 /home/shs/bin/runme</span></span></code></pre></div><p>在下面的命令中，我们从主目录（<code>~</code>）开始，限制搜索的深度（即我们将搜索子目录的层数），并只查看在最近一天内创建或修改的文件（<code>mtime</code> 设置）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -maxdepth 2 -mtime -1 -ls</span></span>
<span class="line"><span> 407928 4 drwxr-xr-x 21 shs shs 4096 Sep 21 12:03 /home/shs</span></span>
<span class="line"><span> 394006 8 -rw------- 1 shs shs 5909 Sep 21 08:18 /home/shs/.bash_history</span></span>
<span class="line"><span> 399612 4 -rw------- 1 shs shs 53 Sep 21 08:50 /home/shs/.Xauthority</span></span>
<span class="line"><span> 399615 4 drwxr-xr-x 2 shs shs 4096 Sep 21 09:32 /home/shs/Downloads</span></span></code></pre></div><h3 id="不仅仅是列出文件" tabindex="-1">不仅仅是列出文件 <a class="header-anchor" href="#不仅仅是列出文件" aria-label="Permalink to “不仅仅是列出文件”">​</a></h3><p>使用 <code>-exec</code> 选项，在您使用 <code>find</code> 命令找到文件后可以以某种方式更改文件。您只需参照 <code>-exec</code> 选项即可运行相应的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -exec chmod 700 {} \\;</span></span>
<span class="line"><span>$ find . -name runme -ls</span></span>
<span class="line"><span> 397132 4 -rwx------ 1 shs shs 18 Sep 15 16:06 ./bin/runme</span></span></code></pre></div><p>在这条命令中，<code>{}</code> 代表文件名。此命令将更改当前目录和子目录中任何名为 <code>runme</code> 的文件的权限。</p><p>把您想运行的任何命令放在 <code>-exec</code> 选项之后，并使用类似于上面命令的语法即可。</p><h3 id="其他搜索条件" tabindex="-1">其他搜索条件 <a class="header-anchor" href="#其他搜索条件" aria-label="Permalink to “其他搜索条件”">​</a></h3><p>如上面的例子所示，您还可以通过其他条件进行搜索：文件的修改时间、所有者、权限等。以下是一些示例。</p><h4 id="根据用户查找文件" tabindex="-1">根据用户查找文件 <a class="header-anchor" href="#根据用户查找文件" aria-label="Permalink to “根据用户查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -user peanut</span></span>
<span class="line"><span>/home/peanut</span></span>
<span class="line"><span>/home/peanut/.bashrc</span></span>
<span class="line"><span>/home/peanut/.bash_logout</span></span>
<span class="line"><span>/home/peanut/.profile</span></span>
<span class="line"><span>/home/peanut/examples.desktop</span></span></code></pre></div><h4 id="根据权限查找文件" tabindex="-1">根据权限查找文件 <a class="header-anchor" href="#根据权限查找文件" aria-label="Permalink to “根据权限查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -perm 777</span></span>
<span class="line"><span>/home/shs/whatever</span></span>
<span class="line"><span>/home/oops</span></span></code></pre></div><h4 id="根据修改时间查找文件" tabindex="-1">根据修改时间查找文件 <a class="header-anchor" href="#根据修改时间查找文件" aria-label="Permalink to “根据修改时间查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -mtime +100</span></span>
<span class="line"><span>/home/shs/.mozilla/firefox/krsw3giq.default/gmp-gmpopenh264/1.6/gmpopenh264.info</span></span>
<span class="line"><span>/home/shs/.mozilla/firefox/krsw3giq.default/gmp-gmpopenh264/1.6/libgmpopenh264.so</span></span></code></pre></div><h4 id="通过比较修改时间查找文件" tabindex="-1">通过比较修改时间查找文件 <a class="header-anchor" href="#通过比较修改时间查找文件" aria-label="Permalink to “通过比较修改时间查找文件”">​</a></h4><p>像这样的命令可以让您找到修改时间较近的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /var/log -newer /var/log/syslog</span></span>
<span class="line"><span>/var/log/auth.log</span></span></code></pre></div><h3 id="寻找重复的文件" tabindex="-1">寻找重复的文件 <a class="header-anchor" href="#寻找重复的文件" aria-label="Permalink to “寻找重复的文件”">​</a></h3><p>如果您正在清理磁盘空间，则可能需要删除较大的重复文件。确定文件是否真正重复的最好方法是使用 <code>fdupes</code> 命令。此命令使用 md5 校验和来确定文件是否具有相同的内容。使用 <code>-r</code>（递归）选项，<code>fdupes</code> 将在一个目录下并查找具有相同校验和而被确定为内容相同的文件。</p><p>如果以 root 身份运行这样的命令，您可能会发现很多重复的文件，但是很多文件都是创建时被添加到主目录的启动文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># fdupes -rn /home &gt; /tmp/dups.txt</span></span>
<span class="line"><span># more /tmp/dups.txt</span></span>
<span class="line"><span>/home/jdoe/.profile</span></span>
<span class="line"><span>/home/tsmith/.profile</span></span>
<span class="line"><span>/home/peanut/.profile</span></span>
<span class="line"><span>/home/rocket/.profile</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/home/jdoe/.bashrc</span></span>
<span class="line"><span>/home/tsmith/.bashrc</span></span>
<span class="line"><span>/home/peanut/.bashrc</span></span>
<span class="line"><span>/home/rocket/.bashrc</span></span></code></pre></div><p>同样，您可能会在 <code>/usr</code> 中发现很多重复的但不该删除的配置文件。所以，请谨慎利用 <code>fdupes</code> 的输出。</p><p><code>fdupes</code> 命令并不总是很快，但是要记住，它正在对许多文件运行校验和来做比较，你可能会意识到它是多么有效。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>有很多方法可以在 Linux 系统上查找文件。如果您可以描述清楚您正在寻找什么，上面的命令将帮助您找到目标。</p><hr>`,59)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3227075/linux/mastering-file-searches-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3227075/linux/mastering-file-searches-on-linux.html",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),n(e,{href:"https://github.com/jessie-pang"},{default:i(()=>[...s[3]||(s[3]=[a("jessie-pang",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const y=l(r,[["render",c]]);export{w as __pageData,y as default};
